model:
rachana: 1
sutra: customer
version: 1
description: 
match: { kind: customer, priority: 10 }
title: { pill: "Retail banking · Customer", id: "$.customerId" }
strip:
  - { label: "Customer", bind: "$.name" }
  - { label: "Segment", bind: "$.segment" }
  - { label: "Deposits", bind: "$.totalDeposits", fmt: "compact", emphasis: true }
  - { label: "Lending", bind: "$.totalLending", fmt: "compact" }
  - { label: "KYC risk", bind: "$.kycRisk", tone: "status" }
  - { label: "Customer since", bind: "$.since", fmt: "date" }
panels:
  - id: products
    kind: table
    title: "Products held"
    key: "F2"
    rows: "$.products"
    columns:
      - { label: "Product", bind: "@.product" }
      - { label: "Account", bind: "@.id" }
      - { label: "Balance", bind: "@.balance", fmt: "signed2", tone: "sign", total: true }
  - id: profile
    kind: kv
    title: "Profile"
    key: "F3"
    area: right
    rows: "$.profile"
  - id: built
    kind: provenance
    title: "How this view was built"
  - id: refs
    kind: links
    title: "Linked entities"
    code: "REFS"
    area: right
keys: { F7: "link($.branch, 'branch')", F8: "impact", F9: "raw" }
